-- ══════════════════════════════════════════════════════════════════════════════
-- D&D 5e — MAGIAS E TALENTOS
--
-- Rode no SQL Editor do Supabase. Pode rodar de novo quando o app trouxer uma
-- versão nova: as linhas do livro são atualizadas e as criadas pela mesa
-- (homebrew = true) não são tocadas.
--
-- O app só LÊ estas tabelas. Para cadastrar uma magia ou talento da casa, use o
-- Table Editor do Supabase e marque homebrew = true. Se o Supabase cair, o app
-- usa a cópia que vem junto com ele (src/dados/*.json).
--
-- resumo: texto curto feito para o app; a regra completa está na página do
-- Livro do Jogador (coluna pagina).
-- ══════════════════════════════════════════════════════════════════════════════

create table if not exists public.dnd_magias (
    id             text primary key,
    nome           text not null,
    nivel          smallint not null check (nivel between 0 and 9),
    escola         text not null,
    ritual         boolean not null default false,
    tempo          text,
    alcance        text,
    componentes    text,
    material       text,
    duracao        text,
    concentracao   boolean not null default false,
    classes        text[] not null default '{}',
    ataque         text check (ataque in ('corpo', 'distancia')),
    resistencia    text check (resistencia in ('for', 'des', 'con', 'int', 'sab', 'car')),
    dano           text,          -- "8d6 fogo"
    cura           text,          -- "1d8"
    superior       text,          -- dado a mais por nível de espaço acima do da magia
    escala_truque  boolean not null default false,
    resumo         text,
    pagina         smallint,
    icone          text,          -- game-icons.net, "autor/nome"
    homebrew       boolean not null default false,
    ativo          boolean not null default true,
    atualizado_em  timestamptz not null default now()
);

create table if not exists public.dnd_talentos (
    id             text primary key,
    nome           text not null,
    descricao      text,
    requisito      jsonb,         -- { atributo: { for: 13 } } · { armadura: 'media' } · { conjurador: true }
    aumento        jsonb,         -- +1 num atributo: { fixo: 'con' } ou { de: ['for', 'des'] }
    escolhas       jsonb,         -- escolhas próprias do talento (idiomas, perícias...)
    efeitos        jsonb not null default '{}'::jsonb,  -- iniciativa, deslocamento, pvPorNivel, recurso...
    pagina         smallint,
    icone          text,
    homebrew       boolean not null default false,
    ativo          boolean not null default true,
    atualizado_em  timestamptz not null default now()
);

alter table public.dnd_magias enable row level security;
alter table public.dnd_talentos enable row level security;
drop policy if exists dnd_magias_leitura on public.dnd_magias;
drop policy if exists dnd_talentos_leitura on public.dnd_talentos;
create policy dnd_magias_leitura on public.dnd_magias for select to authenticated using (true);
create policy dnd_talentos_leitura on public.dnd_talentos for select to authenticated using (true);

insert into public.dnd_magias
    (id, nome, nivel, escola, ritual, tempo, alcance, componentes, material, duracao, concentracao, classes,
     ataque, resistencia, dano, cura, superior, escala_truque, resumo, pagina, icone)
