('conjurar-celestial', 'Conjurar Celestial', 7, 'conjuração', false, '1 minuto', '27 metros', 'V, S', null, 'Concentração, até 1 hora', true, array['clerigo']::text[], null, null, null, null, null, false, 'Invoca um celestial.', 230, 'lorc/angel-wings'),
