('mansao-magnifica-de-mordenkainen', 'Mansão Magnifica de Mordenkainen', 7, 'conjuração', false, '1 minuto', '90 metros', 'V, S, M', 'um portal em miniatura esculpido em marfim, um pedaço de mármore polido e uma pequena colher de prata, cada item valendo, no mínimo, 5 po', '24 horas', false, array['bardo', 'mago']::text[], null, null, null, null, null, false, 'Mansão extradimensional com servos.', 256, 'lorc/magic-portal'),
('miragem', 'Miragem', 7, 'ilusão', false, '10 minutos', 'Visão', 'V, S', null, '10 dias', false, array['bardo', 'druida', 'mago']::text[], null, null, null, null, null, false, 'Muda a aparência de uma grande área por dias.', 259, 'delapouite/carnival-mask'),
('palavra-divina', 'Palavra Divina', 7, 'evocação', false, '1 ação bônus', '9 metros', 'V', null, 'Instantânea', false, array['clerigo']::text[], null, 'car', null, null, null, false, 'Palavra que fere e bane conforme os PV (CAR).', 267, 'lorc/energy-arrow'),
('prisao-de-energia', 'Prisão de Energia', 7, 'evocação', false, '1 ação', '30 metros', 'V, S, M', 'pó de rubi no valor de 1.500 po', '1 hora', false, array['bardo', 'bruxo', 'mago']::text[], null, 'car', null, null, null, false, 'Prisão de força ao redor de uma área.', 271, 'lorc/energy-arrow'),
