('rajada-prismatica', 'Rajada Prismática', 7, 'evocação', false, '1 ação', 'Pessoal (cone de 18 metros)', 'V, S', null, 'Instantânea', false, array['feiticeiro', 'mago']::text[], null, 'des', '10d6 fogo', null, null, false, 'Cone de raios coloridos com efeitos diferentes (DES).', 275, 'lorc/energy-arrow'),
('regeneracao', 'Regeneração', 7, 'transmutação', false, '1 minuto', 'Toque', 'V, S, M', 'uma conta de oração e água benta', '1 hora', false, array['bardo', 'clerigo', 'druida']::text[], null, null, null, '4d8', null, false, 'Cura e regenera membros perdidos.', 278, 'zeromancer/heart-plus'),
('ressurreicao', 'Ressurreição', 7, 'necromancia', false, '1 hora', 'Toque', 'V, S, M', 'um diamante valendo, no mínimo, 1.000 po, consumido pela magia', 'Instantânea', false, array['bardo', 'clerigo']::text[], null, null, null, null, null, false, 'Traz de volta quem morreu há até um século.', 278, 'zeromancer/heart-plus'),
('simbolo', 'Símbolo', 7, 'abjuração', false, '1 minuto', 'Toque', 'V, S, M', 'mercúrio, fósforo e pó de diamante e opala, com um valor total de, no mínimo, 1.000 po, consumidos pela magia', 'Até ser dissipada ou ativada', false, array['bardo', 'clerigo', 'mago']::text[], null, 'sab', '10d10 necrótico', null, null, false, 'Glifo com um efeito poderoso ao ser ativado.', 281, 'lorc/star-swirl'),
('simulacro', 'Simulacro', 7, 'ilusão', false, '12 horas', 'Toque', 'V, S, M', 'neve ou gelo em quantidade suficiente para fazer uma cópia em tamanho real da criatura duplicada; algum cabelo, recortes de unha ou outro pedaço do corpo da criatura, colocado dentro da neve ou gelo; e pó de rubi no valor de 1.500 po, polvilhado sobre a duplicata e consumido pela magia', 'Até ser dissipada', false, array['mago']::text[], null, null, null, null, null, false, 'Cria uma cópia de uma criatura feita de neve.', 282, 'delapouite/transform'),
('teletransporte', 'Teletransporte', 7, 'conjuração', false, '1 ação', '3 metros', 'V', null, 'Instantânea', false, array['bardo', 'feiticeiro', 'mago']::text[], null, null, '3d10 energia', null, null, false, 'Leva você e outros a qualquer lugar do plano.', 286, 'lorc/teleport'),
('tempestade-de-fogo', 'Tempestade de Fogo', 7, 'evocação', false, '1 ação', '45 metros', 'V, S', null, 'Instantânea', false, array['clerigo', 'druida', 'feiticeiro']::text[], null, 'des', '7d10 fogo', null, null, false, 'Chamas em vários cubos de 3 m (DES).', 287, 'lorc/fire-wave'),
('viagem-planar', 'Viagem Planar', 7, 'conjuração', false, '1 ação', 'Toque', 'V, S, M', 'uma haste metálica bifurcada valendo, no mínimo, 250 po, sintonizada com um plano de existência em particular', 'Instantânea', false, array['bruxo', 'clerigo', 'druida', 'feiticeiro', 'mago']::text[], 'corpo', 'car', null, null, null, false, 'Leva até oito criaturas a outro plano.', 289, 'lorc/portal'),
('antipatia-simpatia', 'Antipatia/Simpatia', 8, 'encantamento', false, '1 hora', '18 metros', 'V, S, M', 'ou um pedaço de alume embebido em vinagre para o efeito de antipatia, ou uma gota de mel para o efeito de simpatia', '10 dias', false, array['druida', 'mago']::text[], null, 'sab', null, null, null, false, 'Atrai ou repele um tipo de criatura.', 218, 'lorc/charm'),
('aura-sagrada', 'Aura Sagrada', 8, 'abjuração', false, '1 ação', 'Pessoal', 'V, S, M', 'um minúsculo relicário valendo, no mínimo, 1.000 po, contendo uma relíquia sagrada, como um pedaço de tecido do robe de um santo ou um pedaço de pergaminho de um texto religioso', 'Concentração, até 1 minuto', true, array['clerigo']::text[], null, 'con', null, null, null, false, 'Aura de luz: vantagem nas resistências e desvantagem para atacar aliados.', 222, 'lorc/angel-wings'),
('campo-antimagia', 'Campo Antimagia', 8, 'abjuração', false, '1 ação', 'Pessoal (3 metros de raio)', 'V, S, M', 'um punhado de pó de ferro ou limalhas de ferro', 'Concentração, até 1 hora', true, array['clerigo', 'mago']::text[], null, null, null, null, null, false, 'Esfera onde magia não funciona.', 225, 'lorc/shield-reflect'),
('clone', 'Clone', 8, 'necromancia', false, '1 hora', 'Toque', 'V, S, M', 'um diamante valendo, no mínimo, 1.000 po e, no mínimo 3 centímetros cúbicos de carne da criatura que será clonada, consumida pela magia, e um receptáculo valendo, no mínimo, 2.000 po que tenha uma tampa selada e seja grande o suficiente para comportar uma criatura Média, como uma urna enorme, um caixão, um cisto cheio de lama no solo ou um recipiente de cristal cheio de água salgada', 'Instantânea', false, array['mago']::text[], null, null, null, null, null, false, 'Corpo reserva para quando você morrer.', 228, 'delapouite/transform'),
('controlar-o-clima', 'Controlar o Clima', 8, 'transmutação', false, '10 minutos', 'Pessoal (7,5 quilômetros de raio)', 'V, S, M', 'incenso aceso e pedaços de terra e madeira misturados em água', 'Concentração, até 8 horas', true, array['clerigo', 'druida', 'mago']::text[], null, null, null, null, null, false, 'Muda o clima numa grande área.', 233, 'delapouite/fog'),
('dominar-monstro', 'Dominar Monstro', 8, 'encantamento', false, '1 ação', '18 metros', 'V, S', null, 'Concentração, até 1 hora', true, array['bardo', 'bruxo', 'feiticeiro', 'mago']::text[], null, 'sab', null, null, null, false, 'Controla uma criatura qualquer (SAB).', 241, 'delapouite/brain-tentacle'),
('enfraquecer-intelecto', 'Enfraquecer Intelecto', 8, 'encantamento', false, '1 ação', '45 metros', 'V, S, M', 'um punhado de barro, cristal, vidro ou esferas minerais', 'Instantânea', false, array['bardo', 'bruxo', 'druida', 'mago']::text[], null, 'int', '4d6 psíquico', null, null, false, 'Reduz INT e CAR a 1 (INT).', 243, 'delapouite/brain-tentacle'),
('explosao-solar', 'Explosão Solar', 8, 'evocação', false, '1 ação', '45 metros', 'V, S, M', 'fogo e um pedaço de pedra do sol', 'Instantânea', false, array['druida', 'feiticeiro', 'mago']::text[], null, 'con', '12d6 radiante', null, null, false, 'Luz do sol numa área grande: dano e cegueira (CON).', 246, 'lorc/sunbeams'),
