('alterar-forma', 'Alterar Forma', 9, 'transmutação', false, '1 ação', 'Pessoal', 'V, S, M', 'uma argola de jade valendo, no mínimo, 1.500 po, que você deve colocar na sua cabeça antes de conjurar a magia', 'Concentração, até 1 hora', true, array['druida', 'mago']::text[], null, null, null, null, null, false, 'Assume a forma de outras criaturas.', 216, 'delapouite/transform'),
