('muralha-prismatica', 'Muralha Prismática', 9, 'abjuração', false, '1 ação', '18 metros', 'V, S', null, '10 minutos', false, array['mago']::text[], null, 'con', '10d6 fogo', null, null, false, 'Muralha de sete camadas coloridas.', 263, 'lorc/energy-arrow'),
