('palavra-de-poder-matar', 'Palavra de Poder Matar', 9, 'encantamento', false, '1 ação', '18 metros', 'V', null, 'Instantânea', false, array['bardo', 'bruxo', 'feiticeiro', 'mago']::text[], null, null, null, null, null, false, 'Mata uma criatura com até 100 PV.', 267, 'lorc/tombstone'),
('parar-o-tempo', 'Parar o Tempo', 9, 'transmutação', false, '1 ação', 'Pessoal', 'V', null, 'Instantânea', false, array['feiticeiro', 'mago']::text[], null, null, null, null, null, false, 'Para o tempo para todos menos você por alguns turnos.', 267, 'lorc/hourglass'),
('portal', 'Portal', 9, 'conjuração', false, '1 ação', '18 metros', 'V, S, M', 'um diamante valendo, no mínimo, 5.000 po', 'Concentração, até 1 minuto', true, array['clerigo', 'feiticeiro', 'mago']::text[], null, null, null, null, null, false, 'Portal para outro plano.', 269, 'lorc/portal'),
('projecao-astral', 'Projeção Astral', 9, 'necromancia', false, '1 hora', '3 metros', 'V, S, M', 'para cada criatura que você afetar com essa magia, você deve fornecer um jacinto valendo, no mínimo, 1.000 po e uma barra de prata com ornamentos esculpidos valendo, no mínimo, 100 po, todos consumidos pela magia', 'Especial', false, array['bruxo', 'clerigo', 'mago']::text[], null, null, null, null, null, false, 'Viaja pelo Plano Astral com aliados.', 271, 'lorc/portal'),
('ressurreicao-verdadeira', 'Ressurreição Verdadeira', 9, 'necromancia', false, '1 hora', 'Toque', 'V, S, M', 'um borrifo de água benta e diamantes valendo, no mínimo, 25.000 po, consumidos pela magia', 'Instantânea', false, array['clerigo', 'druida']::text[], null, null, null, null, null, false, 'Traz de volta qualquer morto, até sem corpo.', 279, 'zeromancer/heart-plus'),
('sexto-sentido', 'Sexto Sentido', 9, 'adivinhação', false, '1 minuto', 'Toque', 'V, S, M', 'uma pena de colibri', '8 horas', false, array['bardo', 'bruxo', 'druida', 'mago']::text[], null, null, null, null, null, false, 'Vantagem em tudo e ninguém tem vantagem contra o alvo.', 281, 'delapouite/all-seeing-eye'),
('tempestade-da-vinganca', 'Tempestade da Vingança', 9, 'conjuração', false, '1 ação', 'Visão', 'V, S', null, 'Concentração, até 1 minuto', true, array['druida']::text[], null, 'con', '2d6 trovejante', null, null, false, 'Tempestade enorme com vários efeitos.', 286, 'lorc/sonic-shout')
on conflict (id) do update set
    nome = excluded.nome, nivel = excluded.nivel, escola = excluded.escola, ritual = excluded.ritual,
    tempo = excluded.tempo, alcance = excluded.alcance, componentes = excluded.componentes, material = excluded.material,
    duracao = excluded.duracao, concentracao = excluded.concentracao, classes = excluded.classes,
    ataque = excluded.ataque, resistencia = excluded.resistencia, dano = excluded.dano, cura = excluded.cura,
    superior = excluded.superior, escala_truque = excluded.escala_truque, resumo = excluded.resumo,
    pagina = excluded.pagina, icone = excluded.icone, atualizado_em = now()
where public.dnd_magias.homebrew = false;

insert into public.dnd_talentos (id, nome, descricao, requisito, aumento, escolhas, efeitos, pagina, icone)
values
('adepto-elemental', 'Adepto Elemental', 'Suas magias ignoram resistência ao tipo escolhido e tratam 1 no dano como 2.', '{"conjurador":true}'::jsonb, null, '[{"id":"tipo","rotulo":"Tipo de dano","tipo":"opcao","qtd":1,"fonte":"tipos-dano-elemental"}]'::jsonb, '{}'::jsonb, 167, 'lorc/fireball'),
('adepto-marcial', 'Adepto Marcial', 'Aprende duas manobras e ganha um dado de superioridade d6 (descanso curto).', null, null, '[{"id":"manobras","rotulo":"Manobras","tipo":"opcao","qtd":2,"fonte":"manobras"}]'::jsonb, '{"recurso":{"id":"superioridade-talento","nome":"Dado de superioridade (d6)","max":1,"recarga":"curto"}}'::jsonb, 167, 'lorc/crossed-swords'),
