on conflict (id) do update set
    nome = excluded.nome, descricao = excluded.descricao, requisito = excluded.requisito, aumento = excluded.aumento,
    escolhas = excluded.escolhas, efeitos = excluded.efeitos, pagina = excluded.pagina, icone = excluded.icone,
    atualizado_em = now()
where public.dnd_talentos.homebrew = false;

-- Conferência: deve dar 361 magias e 42 talentos
select (select count(*) from public.dnd_magias where not homebrew) as magias,
       (select count(*) from public.dnd_talentos where not homebrew) as talentos;
